CREATE TABLE public.cw_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, casting_at timestamptz NOT NULL, location text NOT NULL DEFAULT '', mission_start date NOT NULL, mission_end date NOT NULL, mission_location text NOT NULL DEFAULT '', timezone text NOT NULL DEFAULT 'Africa/Douala', required_evaluations integer NOT NULL DEFAULT 1 CHECK (required_evaluations BETWEEN 1 AND 20), archived boolean NOT NULL DEFAULT false, next_number integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.cw_events TO service_role;
ALTER TABLE public.cw_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.cw_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.cw_events(id), user_id uuid NOT NULL, display_name text NOT NULL, role text NOT NULL CHECK (role IN ('reception','jury')), UNIQUE(event_id,user_id));
GRANT ALL ON public.cw_members TO service_role;
ALTER TABLE public.cw_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.cw_people (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL, phone text NOT NULL, normalized_phone text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.cw_people TO service_role;
ALTER TABLE public.cw_people ENABLE ROW LEVEL SECURITY;
CREATE INDEX cw_people_phone_idx ON public.cw_people(normalized_phone);
CREATE TABLE public.cw_rubrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.cw_events(id), version integer NOT NULL DEFAULT 1, criteria jsonb NOT NULL, locked_at timestamptz, UNIQUE(event_id,version));
GRANT ALL ON public.cw_rubrics TO service_role;
ALTER TABLE public.cw_rubrics ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.cw_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.cw_events(id), person_id uuid NOT NULL REFERENCES public.cw_people(id), number integer NOT NULL DEFAULT 0, position text NOT NULL, status text NOT NULL DEFAULT 'registered' CHECK (status IN ('registered','present','waiting','evaluating','evaluated','absent','withdrawn')), arrived_at timestamptz, queue_order integer, jury_ids uuid[] NOT NULL DEFAULT '{}', availability jsonb NOT NULL DEFAULT '[]', briefing_available boolean NOT NULL DEFAULT false, constraints text NOT NULL DEFAULT '', admin_notes text NOT NULL DEFAULT '', dossier_checked boolean NOT NULL DEFAULT false, decision text NOT NULL DEFAULT 'pending' CHECK (decision IN ('pending','selected','reserve','rejected','withdrawn')), decision_reason text NOT NULL DEFAULT '', demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,number), UNIQUE(event_id,person_id));
GRANT ALL ON public.cw_applications TO service_role;
ALTER TABLE public.cw_applications ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.cw_evaluations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.cw_applications(id) ON DELETE CASCADE, juror_id uuid NOT NULL, rubric_id uuid NOT NULL REFERENCES public.cw_rubrics(id), scores jsonb NOT NULL DEFAULT '{}', comments jsonb NOT NULL DEFAULT '{}', appreciation text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','validated')), updated_at timestamptz NOT NULL DEFAULT now(), validated_at timestamptz, UNIQUE(application_id,juror_id));
GRANT ALL ON public.cw_evaluations TO service_role;
ALTER TABLE public.cw_evaluations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.cw_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.cw_events(id), name text NOT NULL, quota integer NOT NULL DEFAULT 0 CHECK (quota BETWEEN 0 AND 1000), welcome_required boolean NOT NULL DEFAULT false);
GRANT ALL ON public.cw_posts TO service_role;
ALTER TABLE public.cw_posts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.cw_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.cw_applications(id) ON DELETE CASCADE, post_id uuid NOT NULL REFERENCES public.cw_posts(id), day date NOT NULL, start_time time NOT NULL, end_time time NOT NULL, CHECK (end_time > start_time));
GRANT ALL ON public.cw_assignments TO service_role;
ALTER TABLE public.cw_assignments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.cw_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.cw_events(id), actor_id uuid NOT NULL, action text NOT NULL, target_id uuid, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.cw_audit TO service_role;
ALTER TABLE public.cw_audit ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.cw_allocate_number() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN UPDATE public.cw_events SET next_number = next_number + 1 WHERE id = NEW.event_id RETURNING next_number INTO NEW.number; RETURN NEW; END; $$;
CREATE TRIGGER cw_number BEFORE INSERT ON public.cw_applications FOR EACH ROW EXECUTE FUNCTION public.cw_allocate_number();
CREATE FUNCTION public.cw_guard_evaluation() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ DECLARE c jsonb; item jsonb; app_event uuid; rubric_event uuid; BEGIN SELECT event_id INTO app_event FROM public.cw_applications WHERE id=NEW.application_id; SELECT event_id, criteria INTO rubric_event,c FROM public.cw_rubrics WHERE id=NEW.rubric_id FOR UPDATE; IF app_event IS DISTINCT FROM rubric_event THEN RAISE EXCEPTION 'Grille incompatible'; END IF; UPDATE public.cw_rubrics SET locked_at=coalesce(locked_at,now()) WHERE id=NEW.rubric_id; FOR item IN SELECT value FROM jsonb_array_elements(c) LOOP IF NEW.scores ? (item->>'key') AND NEW.scores->(item->>'key') <> 'null'::jsonb THEN IF jsonb_typeof(NEW.scores->(item->>'key')) <> 'number' OR (NEW.scores->>(item->>'key'))::numeric NOT BETWEEN 0 AND 5 OR (NEW.scores->>(item->>'key'))::numeric <> trunc((NEW.scores->>(item->>'key'))::numeric) THEN RAISE EXCEPTION 'Niveau invalide'; END IF; ELSIF NEW.status='validated' THEN RAISE EXCEPTION 'Tous les critères sont obligatoires'; END IF; END LOOP; RETURN NEW; END; $$;
CREATE TRIGGER cw_evaluation_guard BEFORE INSERT OR UPDATE ON public.cw_evaluations FOR EACH ROW EXECUTE FUNCTION public.cw_guard_evaluation();
CREATE FUNCTION public.cw_guard_rubric() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF OLD.locked_at IS NOT NULL AND NEW.criteria IS DISTINCT FROM OLD.criteria THEN RAISE EXCEPTION 'Grille verrouillée'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER cw_rubric_guard BEFORE UPDATE ON public.cw_rubrics FOR EACH ROW EXECUTE FUNCTION public.cw_guard_rubric();
REVOKE ALL ON FUNCTION public.cw_allocate_number(), public.cw_guard_evaluation(), public.cw_guard_rubric() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.cw_allocate_number(), public.cw_guard_evaluation(), public.cw_guard_rubric() TO service_role;